mapper.select:
SELECT COUNT(1)
FROM channel_user
WHERE enterprise_id = #{enterpriseId}
  AND factory_id = #{factoryId}
  AND id_card_no = #{idCardNo}
  AND deleted = 1
  AND employee_status NOT IN (8, 9)

    AND id != #{excludedId}

mapper.update:
UPDATE channel_user SET policy_type = #{policyType}, user_policy_detail = #{userDetail}, channel_policy_detail = #{channelDetail}, update_time = NOW() WHERE enterprise_id = #{enterpriseId} AND deleted = 1 AND factory_id = #{factoryId}
AND channel_id = #{channelId}
AND employee_status = 1
AND (policy_type IS NULL OR user_policy_detail IS NULL OR channel_policy_detail IS NULL)

mapper.select:
SELECT cu.id, cu.user_name AS userName, cu.id_card_no AS idCardNo FROM channel_user cu WHERE cu.enterprise_id = #{enterpriseId} AND cu.deleted = 1
AND cu.channel_id = #{channelId}
ORDER BY CASE WHEN cu.employee_status = 8 THEN 1 ELSE 0 END ASC, cu.create_time DESC, cu.id DESC
